"""Additive commercial marketplace structures. Existing order snapshots stay intact."""
from .schema_utils import criar_tabela, criar_sequence, criar_coluna

TABLES = {
    'MP_FORNECEDOR': '''CREATE TABLE MP_FORNECEDOR (ID_FORNECEDOR INTEGER NOT NULL PRIMARY KEY, ID_BARBEARIA INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), NOME VARCHAR(160) NOT NULL, DOCUMENTO VARCHAR(30), EMAIL VARCHAR(200), TELEFONE VARCHAR(30), OBSERVACOES VARCHAR(2000), ATIVO SMALLINT DEFAULT 1 NOT NULL)''',
    'MP_COMERCIAL': '''CREATE TABLE MP_COMERCIAL (ID_PRODUTO INTEGER NOT NULL PRIMARY KEY REFERENCES MP_PRODUTO(ID_PRODUTO), ID_FORNECEDOR INTEGER REFERENCES MP_FORNECEDOR(ID_FORNECEDOR), CUSTO_COMPRA DECIMAL(12,2), PROMOCAO_PRECO DECIMAL(12,2), PROMOCAO_INICIO DATE, PROMOCAO_FIM DATE, LANCAMENTO_ATE DATE)''',
    'MP_VARIACAO': '''CREATE TABLE MP_VARIACAO (ID_VARIACAO INTEGER NOT NULL PRIMARY KEY, ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), NOME VARCHAR(160) NOT NULL, SKU VARCHAR(100), TAMANHO VARCHAR(80), COR VARCHAR(80), VOLUME VARCHAR(80), PRECO DECIMAL(12,2) NOT NULL CHECK(PRECO>0), CUSTO_COMPRA DECIMAL(12,2), ESTOQUE INTEGER DEFAULT 0 NOT NULL CHECK(ESTOQUE>=0), ATIVO SMALLINT DEFAULT 1 NOT NULL)''',
    'MP_CARRINHO_VAR': '''CREATE TABLE MP_CARRINHO_VAR (ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_VARIACAO INTEGER NOT NULL REFERENCES MP_VARIACAO(ID_VARIACAO), QUANTIDADE INTEGER NOT NULL CHECK(QUANTIDADE>0), PRIMARY KEY(ID_USUARIO,ID_VARIACAO))''',
    'MP_DESEJO': '''CREATE TABLE MP_DESEJO (ID_USUARIO INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), ID_PRODUTO INTEGER NOT NULL REFERENCES MP_PRODUTO(ID_PRODUTO), PRIMARY KEY(ID_USUARIO,ID_PRODUTO))''',
    'MP_CUPOM': '''CREATE TABLE MP_CUPOM (ID_CUPOM INTEGER NOT NULL PRIMARY KEY, ID_BARBEARIA INTEGER NOT NULL REFERENCES USUARIO(ID_USUARIO), CODIGO VARCHAR(40) NOT NULL, TIPO VARCHAR(15) NOT NULL, VALOR DECIMAL(12,2) NOT NULL, INICIO DATE NOT NULL, FIM DATE NOT NULL, LIMITE_USOS INTEGER NOT NULL, ATIVO SMALLINT DEFAULT 1 NOT NULL, UNIQUE(ID_BARBEARIA,CODIGO))''',
    'MP_CUPOM_USO': '''CREATE TABLE MP_CUPOM_USO (ID_PEDIDO INTEGER NOT NULL PRIMARY KEY REFERENCES MP_PEDIDO(ID_PEDIDO), ID_CUPOM INTEGER NOT NULL REFERENCES MP_CUPOM(ID_CUPOM), ATIVO SMALLINT DEFAULT 1 NOT NULL)''',
    'MP_PEDIDO_COMERCIAL': '''CREATE TABLE MP_PEDIDO_COMERCIAL (ID_PEDIDO INTEGER NOT NULL PRIMARY KEY REFERENCES MP_PEDIDO(ID_PEDIDO), SUBTOTAL_ORIGINAL DECIMAL(12,2) NOT NULL, DESCONTO DECIMAL(12,2) NOT NULL, CODIGO_CUPOM VARCHAR(40), CUSTOS BLOB SUB_TYPE TEXT NOT NULL)''',
}


def migrar_comercial(cur, con):
    for name, ddl in TABLES.items():
        criar_tabela(cur, name, ddl, con)
    for name in ('SEQ_MP_FORNECEDOR', 'SEQ_MP_VARIACAO', 'SEQ_MP_CUPOM'):
        criar_sequence(cur, name, con)
    criar_coluna(cur, 'MP_ESTOQUE', 'ID_VARIACAO', 'INTEGER REFERENCES MP_VARIACAO(ID_VARIACAO)', con)
